400: vec3 LTC_EdgeVectorFormFactor( const in vec3 v1, const in vec3 v2 ) {
401: 	float x = dot( v1, v2 );
402: 	float y = abs( x );
403: 	float a = 0.8543985 + ( 0.4965155 + 0.0145206 * y ) * y;
404: 	float b = 3.4175940 + ( 4.1616724 + y ) * y;
405: 	float v = a / b;
406: 	float theta_sintheta = ( x > 0.0 ) ? v : 0.5 * inversesqrt( max( 1.0 - x * x, 1e-7 ) ) - v;
407: 	return cross( v1, v2 ) * theta_sintheta;
408: }
409: vec3 LTC_Evaluate( const in vec3 N, const in vec3 V, const in vec3 P, const in mat3 mInv, const in vec3 rectCoords[ 4 ] ) {
410: 	vec3 v1 = rectCoords[ 1 ] - rectCoords[ 0 ];
411: 	vec3 v2 = rectCoords[ 3 ] - rectCoords[ 0 ];
412: 	vec3 lightNormal = cross( v1, v2 );
413: 	if( dot( lightNormal, P - rectCoords[ 0 ] ) < 0.0 ) return vec3( 0.0 );
414: 	vec3 T1, T2;
415: 	T1 = normalize( V - N * dot( V, N ) );
416: 	T2 = - cross( N, T1 );
417: 	mat3 mat = mInv * transposeMat3( mat3( T1, T2, N ) );
418: 	vec3 coords[ 4 ];
419: 	coords[ 0 ] = mat * ( rectCoords[ 0 ] - P );
420: 	coords[ 1 ] = mat * ( rectCoords[ 1 ] - P );
421: 	coords[ 2 ] = mat * ( rectCoords[ 2 ] - P );
422: 	coords[ 3 ] = mat * ( rectCoords[ 3 ] - P );
423: 	coords[ 0 ] = normalize( coords[ 0 ] );
424: 	coords[ 1 ] = normalize( coords[ 1 ] );
425: 	coords[ 2 ] = normalize( coords[ 2 ] );
426: 	coords[ 3 ] = normalize( coords[ 3 ] );
427: 	vec3 vectorFormFactor = vec3( 0.0 );
428: 	vectorFormFactor += LTC_EdgeVectorFormFactor( coords[ 0 ], coords[ 1 ] );
429: 	vectorFormFactor += LTC_EdgeVectorFormFactor( coords[ 1 ], coords[ 2 ] );
430: 	vectorFormFactor += LTC_EdgeVectorFormFactor( coords[ 2 ], coords[ 3 ] );
431: 	vectorFormFactor += LTC_EdgeVectorFormFactor( coords[ 3 ], coords[ 0 ] );
432: 	float result = LTC_ClippedSphereFormFactor( vectorFormFactor );
433: 	return vec3( result );
434: }
435: vec3 BRDF_Specular_GGX_Environment( const in vec3 viewDir, const in vec3 normal, const in vec3 specularColor, const in float roughness ) {
436: 	float dotNV = saturate( dot( normal, viewDir ) );
