440: void BRDF_Specular_Multiscattering_Environment( const in GeometricContext geometry, const in vec3 specularColor, const in float roughness, inout vec3 singleScatter, inout vec3 multiScatter ) {
441: 	float dotNV = saturate( dot( geometry.normal, geometry.viewDir ) );
442: 	vec3 F = F_Schlick_RoughnessDependent( specularColor, dotNV, roughness );
443: 	vec2 brdf = integrateSpecularBRDF( dotNV, roughness );
444: 	vec3 FssEss = F * brdf.x + brdf.y;
445: 	float Ess = brdf.x + brdf.y;
446: 	float Ems = 1.0 - Ess;
447: 	vec3 Favg = specularColor + ( 1.0 - specularColor ) * 0.047619;	vec3 Fms = FssEss * Favg / ( 1.0 - Ems * Favg );
448: 	singleScatter += FssEss;
449: 	multiScatter += Fms * Ems;
450: }
